function minimumDeleteSum(s1, s2) {
  const rows = s1.length;
  const cols = s2.length;
  const dp = Array.from({ length: rows + 1 }, () => new Array(cols + 1).fill(0));

  for (let i = 1; i <= rows; i++) {
    dp[i][0] = dp[i - 1][0] + s1.charCodeAt(i - 1);
  }
  for (let j = 1; j <= cols; j++) {
    dp[0][j] = dp[0][j - 1] + s2.charCodeAt(j - 1);
  }
  for (let i = 1; i <= rows; i++) {
    for (let j = 1; j <= cols; j++) {
      if (s1[i - 1] === s2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        const dropFirst = dp[i - 1][j] + s1.charCodeAt(i - 1);
        const dropSecond = dp[i][j - 1] + s2.charCodeAt(j - 1);
        dp[i][j] = Math.min(dropFirst, dropSecond);
      }
    }
  }
  return dp[rows][cols];
}

