function minimumDeleteSum(s1, s2) {
  // Try every subsequence of s1 we could keep; it must also be a subsequence of s2.
  const weight = (text) => [...text].reduce((sum, ch) => sum + ch.charCodeAt(0), 0);
  const isSubsequence = (small, big) => {
    let k = 0;
    for (const ch of big) if (k < small.length && small[k] === ch) k++;
    return k === small.length;
  };
  // chosen works as a binary counter over the positions of s1, starting from "keep nothing".
  const chosen = new Array(s1.length).fill(false);
  let heaviest = 0;
  for (;;) {
    let kept = '';
    for (let b = 0; b < s1.length; b++) if (chosen[b]) kept += s1[b];
    if (isSubsequence(kept, s2)) heaviest = Math.max(heaviest, weight(kept));
    let b = 0;
    while (b < chosen.length && chosen[b]) chosen[b++] = false;
    if (b === chosen.length) break;
    chosen[b] = true;
  }
  return weight(s1) + weight(s2) - 2 * heaviest;
}

