function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const alphabets = ['ab', 'abc', 'az', 'aeiouz', 'abcdefghijklmnopqrstuvwxyz'];
  const letters = alphabets[int(0, alphabets.length - 1)];
  const word = (length) => {
    let text = '';
    for (let i = 0; i < length; i++) text += letters[int(0, letters.length - 1)];
    return text;
  };
  const length = () => size === 'large' ? int(800, 1000) : int(1, 7);
  const s1 = word(length());
  const style = rand();
  if (style < 0.15) return [s1, s1];
  if (style < 0.3) {
    // s2 is s1 with some letters removed, so most of s1 can be kept.
    const s2 = [...s1].filter(() => rand() < 0.7).join('');
    return [s1, s2.length > 0 ? s2 : s1[0]];
  }
  return [s1, word(length())];
}
